public class Repeater {
    public static String repeat(String s, int times) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < times; i++) {
            sb.append(s);
        }
        return sb.toString();
    }
}

after:
public class Repeater {
    public static String repeat(String s, int times, String separator) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < times; i++) {
            if (i > 0) {
                sb.append(separator);
            }
            sb.append(s);
        }
        return sb.toString();
    }
}

