public class Test {
    public static void main(String[] a) {
        if (!(Repeater.repeat("ab", 3, "-").equals("ab-ab-ab"))) throw new AssertionError("three copies");
        if (!(Repeater.repeat("x", 1, ", ").equals("x"))) throw new AssertionError("one copy");
        if (!(Repeater.repeat("x", 0, "-").equals(""))) throw new AssertionError("zero copies");
        System.out.println("PASS");
    }
}
